'use strict';

/**
 * Anime gfx logos (the same ones Kord makes): an anime picture with the text
 * written on it, generated by the NexOracle image API.
 *
 *   .agfx I Am;Codex          (agfx = Kord's gfx / gfx1, agfx2 ... agfx12)
 *
 * The anime artwork comes from the web service, so it can only be generated while
 * that service is online. When it is slow or down, the command automatically sends
 * the built-in local style with the same number instead of failing.
 *
 * Panel variable (optional): NEXORACLE_APIKEY  (default: the free public key)
 */

const { STYLES, renderGfx } = require('./gfxStyles');
const { guard, cleanText, sendImage } = require('./imageKit');

const BASE = 'https://api.nexoracle.com/image-creating';
const API_KEY = process.env.NEXORACLE_APIKEY || 'free_key@maher_apis';
const TIMEOUT_MS = 45_000;
const MAX_BYTES = 15 * 1024 * 1024;

const endpointFor = n => (n === 1 ? 'gfx' : `gfx${n}`);

/** Same parameter order Kord uses for each kind of style. */
function buildUrl(n, parts) {
    const mode = STYLES[n].mode;
    const params = new URLSearchParams({ apikey: API_KEY });
    if (mode === 'two') {
        params.set('text1', parts[1]);
        params.set('text2', parts[0]);
    } else if (mode === 'three') {
        params.set('text1', parts[0]);
        params.set('text2', parts[1]);
        params.set('text3', parts[2]);
    } else {
        params.set('text', parts[0]);
    }
    return `${BASE}/${endpointFor(n)}?${params.toString()}`;
}

function imageKind(buf) {
    if (!buf || buf.length < 12) return null;
    if (buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) return 'image/jpeg';
    if (buf[0] === 0x89 && buf.toString('latin1', 1, 4) === 'PNG') return 'image/png';
    if (buf.toString('latin1', 0, 4) === 'RIFF' && buf.toString('latin1', 8, 12) === 'WEBP') return 'image/webp';
    return null;
}

/** Downloads the anime image. Throws if the service errors or answers with something that is not an image. */
async function fetchAnimeGfx(n, parts) {
    const url = buildUrl(n, parts);
    let lastError;
    for (let attempt = 0; attempt < 2; attempt++) {
        try {
            const res = await fetch(url, {
                headers: { 'User-Agent': 'Mozilla/5.0', Accept: 'image/*,*/*' },
                signal: AbortSignal.timeout(TIMEOUT_MS),
                redirect: 'follow',
            });
            if (!res.ok) throw new Error(`HTTP ${res.status}`);
            if (Number(res.headers.get('content-length')) > MAX_BYTES) throw new Error('image too large');
            const buffer = Buffer.from(await res.arrayBuffer());
            const mimetype = imageKind(buffer);
            if (!mimetype) throw new Error('service did not return an image');
            return { buffer, mimetype };
        } catch (err) {
            lastError = err;
        }
    }
    throw lastError;
}

const HINT = {
    two: '<small text>;<big text>',
    three: '<top text>;<big text>;<bottom text>',
    one: '<text>',
};
const EXAMPLE = {
    two: 'I Am;Codex',
    three: 'I Am;Codex;Dev',
    one: 'Codex',
};

/** Builds the command object for anime gfx style `n`. */
function makeAnimeGfxCommand({ n, name, aliases = [] }) {
    const style = STYLES[n];
    if (!style) throw new Error(`Unknown gfx style ${n}`);

    return {
        name,
        aliases,
        category: 'image',
        reactions: { start: '⏳' },
        description: `Create an anime gfx logo (style ${n}).`,
        usage: `.${name} ${HINT[style.mode]}`,

        async execute(bot, m, args) {
            const prefix = bot.prefix || '.';
            const usage = `*Anime gfx ${n}*\nUsage: ${prefix}${name} ${HINT[style.mode]}\nExample: ${prefix}${name} ${EXAMPLE[style.mode]}`;

            return guard(m, async () => {
                const text = args.join(' ').trim();
                if (!text) return m.reply(usage);

                let parts;
                if (style.mode === 'one') {
                    parts = [cleanText(text.replace(/;/g, ' '), 30)];
                } else {
                    parts = text.split(';').map(p => cleanText(p, 30)).filter(Boolean);
                    const need = style.mode === 'three' ? 3 : 2;
                    if (parts.length < need) {
                        return m.reply(`Please give ${need} texts separated by semicolons.\n\n${usage}`);
                    }
                    parts = parts.slice(0, need);
                }

                try {
                    const { buffer, mimetype } = await fetchAnimeGfx(n, parts);
                    await sendImage(bot, m, buffer, { mimetype });
                } catch (err) {
                    console.warn(`[agfx${n}] anime service unavailable, using built-in style:`, err.message);
                    await sendImage(bot, m, renderGfx(n, parts), { mimetype: 'image/png' });
                    await m.reply('_The anime generator is busy right now, so this is the built-in style. Try again in a moment for the anime version._');
                }
            });
        },
    };
}

module.exports = { makeAnimeGfxCommand, fetchAnimeGfx, buildUrl };
                                    
